def _fetch(self, uri, sub_domain=False):
        """
        Send a HEAD request to URL and print response code if it's not in ignored_error_codes
        :param uri: URI to fuzz
        :param sub_domain: If True, build destination URL with {URL}.{HOST} else {HOST}/{URL}
        """
        if sub_domain:
            url = self.url.format(URL=uri, HOST=self.host)
        else:
            url = self.url.format(HOST=self.host, URL=uri)

        try:
            response = requests.head(url, timeout=self.timeout)
        except requests.exceptions.Timeout:
            self.logger.error("Timeout error")
            return
        except requests.exceptions.ConnectionError:
            self.logger.error("Connection error")
            return
        except requests.exceptions.RequestException as e:
            self.logger.error("Request error: {}".format(e))
            return

        if response.status_code not in self.ignored_error_codes:
            self.logger.info("{} {}".format(response.status_code, url))

